pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address receiver, uint256 amount) public {
        // Restrict inputs to valid ones for the reference contract
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);
        vm.assume(amount <= address(c).balance); // ensure enough balance

        // Deploy a contract that rejects Ether to trigger revert difference
        RejectEther rejecter = new RejectEther();

        // Fund the owner (the deployer) to call sendTo
        vm.deal(address(c), amount);

        // Try to call sendTo from owner to the rejecting contract
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendTo(address,uint256)", address(rejecter), amount));

        // In the reference (transfer), the call should revert because transfer throws on failure
        // In the mutant (send), the call succeeds but send returns false (the call doesn't revert)
        // The property: for a rejecting receiver, the call to sendTo should revert in the reference
        assertTrue(success == false); // if it didn't revert, the buggy behavior is detected
    }
}

contract RejectEther {
    receive() external payable {
        revert();
    }
}

