pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address receiver, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(receiver != address(0));
        vm.assume(amount > 0 && amount <= 1 ether);

        bool success;
        if (caller == address(this)) {
            // caller is the deployer (owner)
            (success,) = address(c).call(abi.encodeCall(c.sendTo, (receiver, amount)));
        } else {
            // caller is not the owner
            vm.prank(caller);
            (success,) = address(c).call(abi.encodeCall(c.sendTo, (receiver, amount)));
        }

        // General rule: The call succeeds if and only if caller is the owner
        assertTrue(success == (caller == address(this)));
    }
}

