pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0) && receiver != address(c) && receiver != address(this));
        vm.assume(amount > 0 && amount <= address(this).balance);

        // Fund the contract and the test contract
        vm.deal(address(c), 1 ether);

        uint256 balanceBefore = address(c).balance;

        // Try to call sendTo as owner (msg.sender == owner)
        vm.prank(address(this)); // Not the owner, but we'll check revert below
        // Actually, the owner is the contract deployer (this contract in test context)
        address owner = address(this);
        vm.prank(owner);

        // Check if call succeeds or reverts
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendTo(address,uint256)", receiver, amount));

        if (success) {
            uint256 balanceAfter = address(c).balance;
            assertTrue(balanceAfter == balanceBefore - amount, "Balance should decrease by amount");
        } else {
            uint256 balanceAfter = address(c).balance;
            assertTrue(balanceAfter == balanceBefore, "Balance should stay same on revert");
        }
    }
}

