import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(this));
        vm.assume(amount > 0 && amount <= address(this).balance);

        uint256 preBalReceiver = receiver == address(0) ? 0 : receiver.balance;
        uint256 preBalContract = address(c).balance;

        vm.prank(c.owner());
        (bool success, ) = address(c).call(
            abi.encodeWithSelector(c.sendTo.selector, receiver, amount)
