            assertTrue(success, "Should succeed for non-zero address");
            assertTrue(receiver.balance == preBalReceiver + amount, "Receiver balance increased by amount");
            assertTrue(address(c).balance == preBalContract - amount, "Contract balance decreased by amount");
        }
    }
}

